import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class UserProfileServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input sanitizer - strips obvious attack patterns
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove HTML tags
        input = input.replaceAll("<[^>]*>", "");
        // Remove javascript: protocol
        input = input.replaceAll("(?i)javascript:", "");
        // Trim whitespace
        return input.trim();
    }

    // Validate session token format
    private boolean isValidSession(String token) {
        if (token == null || token.length() < 16) return false;
        return Pattern.matches("[A-Fa-f0-9]{32,64}", token);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (!isValidSession(sessionToken)) {
            resp.sendError(401, "Invalid session");
            return;
        }

        String searchTerm = req.getParameter("search");
        String department = req.getParameter("dept");

        // Apply custom sanitization
        searchTerm = sanitizeInput(searchTerm);
        department = sanitizeInput(department);

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Search term required");
            return;
        }

        // Length check to prevent buffer-style attacks
        if (searchTerm.length() > 100 || (department != null && department.length() > 50)) {
            resp.sendError(400, "Input too long");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query;
            if (department != null && !department.isEmpty()) {
                query = "SELECT id, display_name, email, department FROM user_profiles " +
                        "WHERE department = '" + department + "' " +
                        "AND (display_name LIKE '%" + searchTerm + "%' " +
                        "OR email LIKE '%" + searchTerm + "%') " +
                        "ORDER BY display_name LIMIT 25";
            } else {
                query = "SELECT id, display_name, email, department FROM user_profiles " +
                        "WHERE display_name LIKE '%" + searchTerm + "%' " +
                        "OR email LIKE '%" + searchTerm + "%' " +
                        "ORDER BY display_name LIMIT 25";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("name", rs.getString("display_name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                results.put(user);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log but don't expose internal details
            getServletContext().log("DB error in profile search", e);
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
